import re, subprocess, os
pats = [re.compile(l.strip(), re.I) for l in open(".hindsight/private.local", encoding="utf-8") if l.strip() and not l.startswith("#")]
home_user = os.path.basename(os.path.expanduser("~"))
files = subprocess.run(["git", "ls-files", "-co", "--exclude-standard"], capture_output=True, text=True).stdout.split()
hits = 0
for f in files:
    if f.startswith((".hindsight/", "graph/")) or not os.path.isfile(f): continue
    try: text = open(f, encoding="utf-8").read()
    except Exception: continue
    for n, line in enumerate(text.splitlines(), 1):
        for i, p in enumerate(pats):
            if p.search(line): hits += 1; print("private pattern #%d at %s:%d" % (i, f, n))
        if re.search(r"(?i)[\\/]users[\\/]+%s\b" % re.escape(home_user), line): hits += 1; print("home path at %s:%d" % (f, n))
print("hits:", hits)
EOF
