B="$TMPDIR/claude/d90e36e63f7c8fd7/26f62b84-1d13-4294-8b86-ea9c33856883/scratchpad"; .venv/Scripts/python.exe - "$B/rw" <<'EOF'
import subprocess, sys, json, collections
def scan(repo, refs):
    g = lambda *a: subprocess.run(["git", "-C", repo] + list(a), capture_output=True).stdout
    seen = set(); bad = collections.Counter()
    for c in g("rev-list", *refs).decode().split():
        for line in g("ls-tree", "-r", c).decode().splitlines():
            meta, path = line.split("\t", 1); b = meta.split()[2]
            if b in seen or not path.endswith((".json", ".jsonl")): continue
            seen.add(b)
            t = g("cat-file", "-p", b).decode("utf-8", "replace")
            if path.endswith(".jsonl"):
                for l in t.splitlines():
                    try: json.loads(l)
                    except Exception: bad[path] += 1
            else:
                try: json.loads(t)
                except Exception: bad[path] += 1
    return dict(bad)
print("original:", scan(".", ["main", "backup/pre-rewrite-origin"]))
print("rewritten:", scan(sys.argv[1], ["--all"]))
EOF

